/** Four-stream timeline generated by the joint Transformer.
 *
 * Every sixteenth-note step holds an accompaniment-rhythm token (R), the active
 * chord (H), the bass pitch (B) and the melody pitch (M). Steps are generated in
 * order, per step R -> H -> B -> M, ahead of playback and in small asynchronous
 * chunks. Musical state is stored in absolute terms (pitch classes, MIDI notes,
 * local keys); tokens are re-encoded relative to the current context window,
 * exactly as the training windows were (joint_data.encode_window):
 *   - H: chord token (quality*12 + root above the window's reference tonic) at the
 *     window start and at every change, HOLD otherwise
 *   - B/M: onset at the window start and at every new note, HOLD while it sounds
 *   - base pitch of B/M: an octave of the reference tonic at or below the context
 * The window holds at most 128 steps; when it is full, generation restarts from a
 * barline 48+ steps back, re-encoding that context (never attention over a cut).
 *
 * Musical constraints are applied as masks on the model's distribution:
 * Hold (no chord changes), Every bar (one new chord per downbeat), Free (changes on
 * beats), edited chords and bass notes, notes already scheduled across a barline,
 * and the playable register of bass and melody.
 */
import {
    loadJointModel, JointDecoder, STREAMS, PAD, UNK, R_ONE, R_MULTI, R_HOLD, H_HOLD, H_CHORD0, REST, HOLD, ONSET0,
    VOCAB, PITCHES, CONTEXT_STEPS, N_SINCE, R_REST, metricalAngles, metricalLevel
} from '../vendor/lib/joint-model.js';

export const mod12 = n => ((n % 12) + 12) % 12;
export const METERS = Object.freeze({
    4: Object.freeze({ id: 2, barlen: 16, beatlen: 4, beats: 4, signature: '4/4' }),
    3: Object.freeze({ id: 1, barlen: 12, beatlen: 4, beats: 3, signature: '3/4' }),
    2: Object.freeze({ id: 0, barlen: 8, beatlen: 4, beats: 2, signature: '2/4' }),
    5: Object.freeze({ id: 11, barlen: 20, beatlen: 4, beats: 5, signature: '5/4' }),
    6: Object.freeze({ id: 5, barlen: 12, beatlen: 6, beats: 3, signature: '6/8' }),
    9: Object.freeze({ id: 6, barlen: 18, beatlen: 6, beats: 4.5, signature: '9/8' }),
    12: Object.freeze({ id: 7, barlen: 24, beatlen: 6, beats: 6, signature: '12/8' })
});
export const BASS_RANGE = Object.freeze([28, 62]);
// Ranges are chosen so every window can encode them: the base sits up to 11 semitones
// below the lowest note, and B/M have 48/36 pitch tokens (training excluded wider windows).
export const MELODY_RANGE = Object.freeze([57, 81]);
const BASS_ANCHOR = 28, MELODY_ANCHOR = 55;   // base octave of the reference tonic, at most this register
const MIN_CONTEXT = 48;                        // steps kept when the window restarts (3 bars of 4/4)
const TOP_P = 0.95;
const CANDIDATES = 6;

export const chordEquals = (a, b) => !!a && !!b && a.root === b.root && a.q === b.q;

/** Nucleus sampling over the allowed tokens of one distribution. */
export function sampleLogits(logits, allowed, { temperature = 1, topP = TOP_P, bias = null, random = Math.random } = {}) {
    const ids = [], values = [];
    let max = -Infinity;
    for (let i = 0; i < logits.length; i++) {
        if (!allowed(i)) continue;
        const v = (logits[i] + (bias ? bias(i) : 0)) / Math.max(0.05, temperature);
        ids.push(i); values.push(v);
        if (v > max) max = v;
    }
    if (!ids.length) return -1;
    let sum = 0;
    for (let k = 0; k < values.length; k++) { values[k] = Math.exp(values[k] - max); sum += values[k]; }
    const order = ids.map((_, k) => k).sort((a, b) => values[b] - values[a]);
    let kept = 0, mass = 0;
    for (const k of order) { mass += values[k] / sum; kept++; if (mass >= topP) break; }
    let total = 0;
    for (let n = 0; n < kept; n++) total += values[order[n]];
    let draw = Math.min(Math.max(Number(random()) || 0, 0), 1 - Number.EPSILON) * total;
    for (let n = 0; n < kept; n++) { draw -= values[order[n]]; if (draw < 0) return ids[order[n]]; }
    return ids[order[kept - 1]];
}

/**
 * Two-stage sampling for streams whose tokens mix "what" and "whether": the event
 * type (continue / rest / new event) is drawn from the model's distribution at
 * temperature 1, and the temperature only sharpens or flattens the choice among the
 * new events (which chord, which pitch). Lower temperatures therefore make choices
 * more conservative without making the music stop moving; with plain temperature
 * scaling the frequent HOLD/REST tokens swallow the distribution.
 * groups: token -> 'event' | 'hold' | 'rest' (only allowed tokens are passed).
 */
export function sampleFactored(logits, allowed, isEvent, { temperature = 1, topP = TOP_P, eventBias = 0, random = Math.random } = {}) {
    let max = -Infinity;
    for (let i = 0; i < logits.length; i++) if (allowed(i)) { const v = logits[i] + (isEvent(i) ? eventBias : 0); if (v > max) max = v; }
    if (max === -Infinity) return -1;
    let eventMass = 0, otherMass = 0;
    for (let i = 0; i < logits.length; i++) {
        if (!allowed(i)) continue;
        const e = Math.exp(logits[i] + (isEvent(i) ? eventBias : 0) - max);
        if (isEvent(i)) eventMass += e; else otherMass += e;
    }
    const draw = Math.min(Math.max(Number(random()) || 0, 0), 1 - Number.EPSILON) * (eventMass + otherMass);
    if (draw < eventMass) return sampleLogits(logits, i => allowed(i) && isEvent(i), { temperature, topP, random });
    return sampleLogits(logits, i => allowed(i) && !isEvent(i), { temperature: 1, topP: 1, random });
}

export class Composer {
    /**
     * planBar(index, previousBar) -> { cond, key, keyAge, sceneSwitch, forceTonic }
     *   cond: { domain, styleId, style, harmonyT, melodyT, density, mode, changeMode, beats, scene }
     */
    constructor({ random = Math.random, planBar, model = loadJointModel(), expression = null, expressionFeedback = false, budgetMs = 6, setTimer = (fn, ms) => globalThis.setTimeout(fn, ms), clearTimer = id => globalThis.clearTimeout(id), onProgress = () => { } } = {}) {
        Object.assign(this, { random, planBar, model, expression, expressionFeedback, budgetMs, setTimer, clearTimer, onProgress });
        this.decoder = new JointDecoder(model);
        this.timeline = 0;
        this.revision = 0;
        this.target = 0;
        this.timer = null;
        this.stats = { positions: 0, generatedSteps: 0, rebuilds: 0, rebuildPositions: 0, lastChunkMs: 0, maxChunkMs: 0, msPerPosition: 1 };
        this.steps = []; this.bars = []; this.waiters = [];
    }

    /** A model change starts a new timeline; never reuse caches from another checkpoint. */
    replaceModel(model) {
        this.stop();
        this.model = model;
        this.decoder = new JointDecoder(model);
        this.win = null;
    }

    /** Start a new timeline from one fully specified step (bar 0, step 0). */
    reset({ key, chord, bass = null, melody = null }) {
        this.timeline++; this.revision++;
        this.steps = []; this.bars = [];
        this.locked = 0;            // steps [0, locked) are scheduled and immutable
        this.pruned = 0;            // steps [0, pruned) were released after scheduling (null)
        this.lockedBars = 0;
        this.holds = [];            // B/M notes scheduled across a barline: {stream, from, until}
        this.clamps = new Map();    // step -> {chord, bassPc}
        this.win = null;
        this.target = 0;
        this.settle();
        const bar = this.newBar(0, null, key);
        const b = bass ?? this.anchorPitch(chord.root, BASS_ANCHOR);
        const step = this.newStep(0, bar);
        Object.assign(step, { R: R_MULTI, chord: { ...chord }, change: true, lastChange: 0, onsetBass: mod12(b), bass: b, bassOn: true, mel: melody ?? -1, melOn: melody !== null && melody >= 0 });
        this.steps.push(step);
        this.onProgress();
    }

    anchorPitch(pc, anchor) { return anchor + mod12(pc - anchor); }

    newBar(index, previous, seedKey = null) {
        const start = previous ? previous.start + previous.barlen : 0;
        const plan = this.planBar(index, previous, this);
        const meter = METERS[plan.cond.beats] || METERS[4];
        const bar = {
            index, start, barlen: meter.barlen, beats: meter.beats, signature: meter.signature, meterId: meter.id, beatlen: meter.beatlen,
            cond: plan.cond, key: { ...(seedKey || plan.key) }, keyAge: plan.keyAge ?? 0, sceneSwitch: plan.sceneSwitch ?? null,
            timeline: this.timeline
        };
        if (plan.forceTonic && index > 0 && !this.clamps.has(start)) this.clamps.set(start, { chord: { root: bar.key.tonic, q: bar.key.mode === 'minor' ? 1 : 0 }, bassPc: bar.key.tonic, reason: 'key' });
        this.bars.push(bar);
        return bar;
    }

    newStep(g, bar) {
        const pos = g - bar.start;
        return {
            g, bar: bar.index, pos, barlen: bar.barlen, beatlen: bar.beatlen, meterId: bar.meterId,
            level: metricalLevel(pos, bar.beatlen), beatphase: pos % bar.beatlen, phrase: bar.index % 8, key: bar.key,
            R: null, chord: null, change: false, lastChange: 0, onsetBass: null, bass: -1, bassOn: false, mel: -1, melOn: false, cands: null, expression: null
        };
    }

    // ---------------------------------------------------------------- queries
    get frontier() { return this.steps.length; }
    barComplete(index) { const bar = this.bars[index]; return !!bar && this.steps.length >= bar.start + bar.barlen; }
    completeBars() { const n = this.bars.length; return n && !this.barComplete(n - 1) ? n - 1 : n; }
    barSteps(index) { const bar = this.bars[index]; return bar ? this.steps.slice(bar.start, Math.min(this.steps.length, bar.start + bar.barlen)) : []; }
    stepAt(g) { return this.steps[g]; }

    /** First step after g whose stream token is not a continuation (release of the note sounding at g). */
    releaseAfter(stream, g) {
        const pitch = stream === 'B' ? 'bass' : 'mel', on = stream === 'B' ? 'bassOn' : 'melOn';
        for (let t = g + 1; t < this.steps.length; t++) {
            const s = this.steps[t];
            if (s[pitch] !== this.steps[g][pitch] || s[on]) return t;
        }
        return this.steps.length;
    }

    /** Chord spans in a bar: [{step, startStep, length, chord, bassPc, continuation}] */
    chordSpans(index) {
        const bar = this.bars[index];
        if (!bar || !this.barComplete(index) || bar.start < this.pruned) return null;
        const spans = [];
        for (let g = bar.start; g < bar.start + bar.barlen; g++) {
            const s = this.steps[g];
            if (g === bar.start || s.change) spans.push({ step: g, onset: s.change ? g : s.lastChange, chord: s.chord, continuation: !s.change, onsetBass: s.onsetBass, key: s.key, length: 0 });
            spans.at(-1).length++;
        }
        return spans;
    }

    bassPcAt(g) { const b = this.steps[g]?.bass; return b >= 0 ? mod12(b) : null; }
    candidates(g) { return this.steps[g]?.cands || []; }

    // ---------------------------------------------------------------- scheduling
    /** Freeze bar `index` (it has been handed to the audio clock). */
    lock(index) {
        const bar = this.bars[index];
        if (!bar || !this.barComplete(index)) throw new Error(`Bar ${index + 1} is not ready`);
        const end = bar.start + bar.barlen;
        this.locked = Math.max(this.locked, end);
        this.lockedBars = Math.max(this.lockedBars, index + 1);
        this.holds = this.holds.filter(h => h.until >= end);
        // A bass or melody note sounding at the barline was scheduled with its full length:
        // keep it held until that release in any regeneration, and release it there.
        for (const stream of ['B', 'M']) {
            const pitch = stream === 'B' ? 'bass' : 'mel', last = this.steps[end - 1];
            if (last[pitch] < 0) continue;
            this.holds.push({ stream, from: end, until: this.releaseAfter(stream, end - 1) });
        }
        for (const g of [...this.clamps.keys()]) if (g < end) this.clamps.delete(g);
        // Long sessions: drop steps that neither the context window nor the chart can reach.
        const keepFrom = Math.min(this.win ? this.win.start : end, this.bars[Math.max(0, index - 12)].start);
        for (let t = this.pruned; t < keepFrom; t++) this.steps[t] = null;
        this.pruned = Math.max(this.pruned, keepFrom);
        return { end, holds: this.holds.map(h => ({ ...h })) };
    }

    /** Discard unscheduled steps from g on (never before the scheduled horizon). */
    truncate(g) {
        g = Math.max(g, this.locked, 1);
        if (g >= this.steps.length && !this.bars.some(b => b.start >= g)) { this.revision++; return g; }
        this.revision++;
        this.steps.length = Math.min(this.steps.length, g);
        while (this.bars.length && this.bars.at(-1).start >= g && this.bars.length > this.lockedBars) this.bars.pop();
        for (const k of [...this.clamps.keys()]) if (k >= g) this.clamps.delete(k);
        const w = this.win;
        if (w) {
            if (g - 1 >= w.start) { const fed = Math.min(w.fed, g - 2); this.decoder.truncate(4 * (fed - w.start + 1)); w.fed = fed; }
            else this.win = null;
        }
        this.onProgress();
        return g;
    }

    /** Regenerate from the start of bar `index` with fresh bar plans (parameter changes). */
    regenerateFromBar(index) {
        index = Math.max(index, this.lockedBars);
        const bar = this.bars[index];
        if (!bar) { this.revision++; return; }
        this.truncate(Math.max(bar.start, 1));
        if (bar.start > 0 && this.bars.length > index && this.bars[index].start >= bar.start) this.bars.length = index;
        if (index === 0) this.replanFirstBar();
    }

    replanFirstBar() {
        const first = this.bars[0];
        if (!first) return;
        const plan = this.planBar(0, null, this);
        const meter = METERS[plan.cond.beats] || METERS[4];
        Object.assign(first, { cond: plan.cond, barlen: meter.barlen, beats: meter.beats, signature: meter.signature, beatlen: meter.beatlen, meterId: meter.id });
        const s = this.steps[0];
        Object.assign(s, { barlen: first.barlen, beatlen: first.beatlen, meterId: first.meterId, level: 0, beatphase: 0 });
        this.win = null;
    }

    /** Replace the chord that starts at step g (and regenerate everything after it). */
    edit(g, chord, bassPc = null) {
        if (g < Math.max(1, this.locked) || g >= this.steps.length + 1) return false;
        this.truncate(g);
        this.clamps.set(g, { chord: { root: mod12(chord.root), q: chord.q }, bassPc: bassPc === null ? null : mod12(bassPc), reason: 'edit' });
        return true;
    }

    // ---------------------------------------------------------------- generation driver
    /** Generate until bars [0, bars) are complete, in chunks between timer ticks.
     * Resolves true once they exist, false if the timeline is replaced first. */
    prefetch(bars) {
        this.target = Math.max(this.target, bars);
        return new Promise(resolve => { this.waiters.push({ bars, timeline: this.timeline, resolve }); this.settle(); this.kick(); });
    }

    settle() {
        const done = this.completeBars();
        this.waiters = this.waiters.filter(w => {
            if (w.timeline !== this.timeline) { w.resolve(false); return false; }
            if (done >= w.bars) { w.resolve(true); return false; }
            return true;
        });
    }

    kick() {
        if (this.timer || this.completeBars() >= this.target) return;
        const tick = () => {
            this.timer = null;
            const t0 = now(), p0 = this.stats.positions;
            while (this.completeBars() < this.target && now() - t0 < this.budgetMs) this.work();
            const ms = now() - t0, positions = this.stats.positions - p0;
            this.stats.lastChunkMs = ms; this.stats.maxChunkMs = Math.max(this.stats.maxChunkMs, ms);
            if (positions >= 8) this.stats.msPerPosition = .8 * this.stats.msPerPosition + .2 * (ms / positions);
            this.settle();
            this.onProgress();
            if (this.completeBars() < this.target) { this.timer = this.setTimer(tick, 0); this.timer?.unref?.(); }
        };
        this.timer = this.setTimer(tick, 0); this.timer?.unref?.();
    }

    /** Decoder positions needed to regenerate from step g to the end of its bar (window rebuild included). */
    positionsToRegenerate(g) {
        const bar = this.bars.find(b => b.start <= g && g < b.start + b.barlen) || { start: g, barlen: 16 };
        const end = bar.start + bar.barlen, w = this.win;
        const keeps = w && g - 1 >= w.start && end - 1 - w.start <= CONTEXT_STEPS - 2;
        return 4 * ((keeps ? 0 : MIN_CONTEXT + 16) + (end - g));
    }

    /** Synchronously complete bar `index` (bounded fallback when a boundary arrives early). */
    ensureBar(index) {
        let guard = 0;
        while (!this.barComplete(index)) {
            this.work();
            if (++guard > 4096) throw new Error('Joint generation did not converge');
        }
        return this.bars[index];
    }

    stop() { if (this.timer) this.clearTimer(this.timer); this.timer = null; this.target = 0; }
    setTarget(bars) { this.target = bars; this.kick(); }

    /** One unit of work: a window-rebuild step (4 known positions) or one generated step. */
    work() {
        const g = this.steps.length;
        const lastBar = this.bars.at(-1);
        const bar = g < lastBar.start + lastBar.barlen ? lastBar : this.newBar(lastBar.index + 1, lastBar);
        const w = this.windowFor(g, bar);
        if (w.fed < g - 2) { this.feedStep(w, w.fed + 1); w.fed++; return; }
        this.generateStep(g, bar, w);
    }

    /** A context window valid for generating step g, rebuilt from an earlier barline when needed. */
    windowFor(g, bar) {
        const global = { domain: bar.cond.domain, style: bar.cond.styleId };
        let w = this.win;
        const fits = w && w.start <= g - 1 && g - 1 - w.start <= CONTEXT_STEPS - 2 && w.domain === global.domain && w.style === global.style && w.timeline === this.timeline;
        if (fits) return w;
        // Restart on a barline with at least MIN_CONTEXT steps of context (or the timeline start).
        let start = 0;
        for (const b of this.bars) if (b.start <= g - 1 - MIN_CONTEXT) start = b.start;
        if (g - 1 - start > CONTEXT_STEPS - 2) start = this.bars.find(b => b.start >= g - 1 - (CONTEXT_STEPS - 2))?.start ?? g - 1;
        const ref = this.steps[start].key, refTonic = ref.tonic;
        const base = (pitchKey, anchor) => {
            let low = this.anchorPitch(refTonic, anchor);
            for (let t = start; t < g; t++) { const p = this.steps[t][pitchKey]; if (p >= 0 && p < low) low = p; }
            return refTonic + 12 * Math.floor((low - refTonic) / 12);
        };
        this.decoder.reset();
        w = this.win = {
            start, timeline: this.timeline, refTonic, refMode: ref.mode === 'minor' ? 1 : 0, domain: global.domain, style: global.style,
            bassBase: base('bass', BASS_ANCHOR), melBase: base('mel', MELODY_ANCHOR), fed: start - 1
        };
        w.global = { domain: w.domain, style: w.style, refmode: w.refMode };
        if (start > 0 || g > 1) { this.stats.rebuilds++; }
        return w;
    }

    // Window-relative encodings --------------------------------------------------
    chordIndex(w, chord) { return chord.q * 12 + mod12(chord.root - w.refTonic); }
    /** Pitch token above the window base; octave-folded as a last resort so the model never reads past its vocabulary. */
    pitchToken(pitch, base, n) { let k = pitch - base; while (k >= n) k -= 12; while (k < 0) k += 12; return ONSET0 + k; }
    token(w, t, s) {
        const st = this.steps[t];
        switch (s) {
            case 0: return st.R;
            case 1: return (t === w.start || st.change) ? H_CHORD0 + this.chordIndex(w, st.chord) : H_HOLD;
            case 2: return st.bass < 0 ? REST : (t === w.start || st.bassOn) ? this.pitchToken(st.bass, w.bassBase, PITCHES.B) : HOLD;
            default: return st.mel < 0 ? REST : (t === w.start || st.melOn) ? this.pitchToken(st.mel, w.melBase, PITCHES.M) : HOLD;
        }
    }
    chordFeature(w, t) {
        const st = this.steps[t];
        const since = Math.min(N_SINCE - 1, t - Math.max(st.lastChange, w.start));
        return { chord: this.chordIndex(w, st.chord), since, change: t === w.start || st.change };
    }
    controls(w, t) {
        const st = this.steps[t];
        return { meter: st.meterId, lkey: mod12(st.key.tonic - w.refTonic) * 2 + (st.key.mode === 'minor' ? 1 : 0), pos: st.pos, level: st.level, phrase: st.phrase };
    }
    angles(w, t) { const st = this.steps[t]; return metricalAngles(t - w.start, st.pos, st.barlen, st.beatphase, st.beatlen); }

    positionInput(w, t, s) {
        const front = [0, 0, 0, 0];
        for (let u = 0; u < 4; u++) if (u !== s) front[u] = this.token(w, u < s ? t + 1 : t, u);
        const nextChord = this.chordFeature(w, t + 1);
        return {
            s, token: this.token(w, t, s), front, global: w.global, next: this.controls(w, t + 1),
            chord: s < 2 ? this.chordFeature(w, t) : nextChord, angQ: this.angles(w, t + 1), angK: this.angles(w, t), nextRoot: nextChord.chord % 12,
            // The experimental pitch head is not yet reliable enough to steer
            // the four-track backbone during free generation. Keep the trained
            // feedback path available for research, but not on the live page.
            extraStep: this.expressionFeedback ? this.expression?.extra(this.steps[t].expression) : null
        };
    }

    feedStep(w, t) {
        for (let s = 0; s < 4; s++) this.decoder.position(this.positionInput(w, t, s), false);
        this.stats.positions += 4; this.stats.rebuildPositions += 4;
    }

    // Generation of one step ------------------------------------------------------
    generateStep(g, bar, w) {
        const prev = this.steps[g - 1], step = this.newStep(g, bar), cond = bar.cond;
        step.chord = prev.chord; step.lastChange = prev.lastChange;
        this.steps.push(step);
        const random = this.random, density = Number.isFinite(cond.density) ? cond.density : 0.5, onsetBias = (density - 0.5) * 2;
        // R ------------------------------------------------------------------
        const features=this.expression?[]:null;
        let logits = this.decoder.position(this.positionInput(w, g - 1, 0), true);
        if(features)features.push(new Float32Array(this.decoder.lastFeature));
        step.R = sampleLogits(logits, i => i >= 2 && !(i === R_HOLD && prev.R === R_REST), { temperature: 1, topP: 1, random, bias: i => (i === R_ONE || i === R_MULTI) ? onsetBias : 0 });
        // H ------------------------------------------------------------------
        const clamp = this.clamps.get(g);
        const beatStep = step.level <= 1;
        let forced = null;
        if (clamp) forced = chordEquals(clamp.chord, prev.chord) ? H_HOLD : H_CHORD0 + this.chordIndex(w, clamp.chord);
        else if (cond.mode === 'hold') forced = H_HOLD;
        else if (cond.changeMode === 'bar' ? step.pos !== 0 : !beatStep) forced = H_HOLD;
        const current = H_CHORD0 + this.chordIndex(w, prev.chord);
        logits = this.decoder.position(this.positionInput(w, g - 1, 1), forced === null || beatStep);
        if(features)features.push(new Float32Array(this.decoder.lastFeature));
        if (beatStep && logits) step.cands = this.topChords(w, logits, current);
        let h = forced;
        if (h === null) {
            // Every bar: a new chord on each downbeat. Free: a chord lasts at most two bars.
            const mustChange = cond.changeMode === 'bar' || g - prev.lastChange >= 2 * bar.barlen;
            h = sampleFactored(logits, i => (i === H_HOLD && !mustChange) || (i >= H_CHORD0 && i !== current), i => i >= H_CHORD0, { temperature: cond.harmonyT, random });
            if (h < 0) h = H_HOLD;
        }
        if (h >= H_CHORD0) {
            const c = h - H_CHORD0;
            step.chord = { root: mod12(c % 12 + w.refTonic), q: Math.floor(c / 12) };
            step.change = !chordEquals(step.chord, prev.chord);
            if (step.change) step.lastChange = g;
        }
        // B ------------------------------------------------------------------
        logits = this.decoder.position(this.positionInput(w, g - 1, 2), true);
        if(features)features.push(new Float32Array(this.decoder.lastFeature));
        this.chooseLine(step, prev, 'B', logits, w, cond.harmonyT, 0, clamp && clamp.bassPc !== null && step.change ? clamp.bassPc : null);
        step.onsetBass = step.change ? (step.bass >= 0 ? mod12(step.bass) : null) : prev.onsetBass;
        // M ------------------------------------------------------------------
        logits = this.decoder.position(this.positionInput(w, g - 1, 3), true);
        if(features)features.push(new Float32Array(this.decoder.lastFeature));
        this.chooseLine(step, prev, 'M', logits, w, cond.melodyT, onsetBias, null);
        if(features)step.expression=this.expression.predict([features[0],features[2],features[3]],
            [0,1,2,3].map(s=>this.token(w,g,s)),random);
        w.fed = g - 1;
        this.stats.positions += 4; this.stats.generatedSteps++;
    }

    topChords(w, logits, current) {
        let max = -Infinity;
        for (let i = H_CHORD0; i < logits.length; i++) if (i !== current && logits[i] > max) max = logits[i];
        let sum = 0;
        const all = [];
        for (let i = H_CHORD0; i < logits.length; i++) { if (i === current) continue; const p = Math.exp(logits[i] - max); sum += p; all.push([i, p]); }
        all.sort((a, b) => b[1] - a[1]);
        return all.slice(0, CANDIDATES).map(([i, p]) => ({ root: mod12((i - H_CHORD0) % 12 + w.refTonic), q: Math.floor((i - H_CHORD0) / 12), p: p / sum }));
    }

    chooseLine(step, prev, stream, logits, w, temperature, onsetBias, pitchClass) {
        const pitchKey = stream === 'B' ? 'bass' : 'mel', onKey = stream === 'B' ? 'bassOn' : 'melOn';
        const base = stream === 'B' ? w.bassBase : w.melBase, [low, high] = stream === 'B' ? BASS_RANGE : MELODY_RANGE;
        const n = PITCHES[stream], sounding = prev[pitchKey] >= 0;
        const hold = this.holds.find(x => x.stream === stream && step.g >= x.from && step.g <= x.until);
        let allowed;
        if (hold && step.g < hold.until && sounding) allowed = i => i === HOLD;
        else {
            const noHold = hold && step.g === hold.until;
            const pitchOk = i => { const p = base + i - ONSET0; return p >= low && p <= high && i - ONSET0 < n; };
            allowed = i => i === REST || (i === HOLD && sounding && !noHold) || (i >= ONSET0 && pitchOk(i));
            if (pitchClass !== null && !(hold && step.g < hold.until)) {
                const strict = i => i >= ONSET0 && pitchOk(i) && mod12(base + i - ONSET0) === pitchClass;
                let any = false;
                for (let i = ONSET0; i < logits.length; i++) if (strict(i)) { any = true; break; }
                if (any) allowed = strict;
            }
        }
        let tok = sampleFactored(logits, allowed, i => i >= ONSET0, { temperature, eventBias: onsetBias, random: this.random });
        if (tok < 0) tok = REST;
        if (tok === HOLD) { step[pitchKey] = prev[pitchKey]; step[onKey] = false; }
        else if (tok === REST) { step[pitchKey] = -1; step[onKey] = false; }
        else { step[pitchKey] = base + tok - ONSET0; step[onKey] = true; }
    }
}

const now = () => (globalThis.performance?.now ? globalThis.performance.now() : Date.now());
export { STREAMS, PAD, UNK, R_ONE, R_MULTI, R_HOLD, H_HOLD, REST, HOLD, ONSET0, VOCAB };
